-- Finite v12 four-sheet acceptance input, not a general workbook serializer.
-- Consumer: tools/create_workbook.py; verified through tests/test_fixture.c.
-- Only the relative Parquet source token varies between canonical/large data.
BEGIN TRANSACTION;
CREATE SCHEMA IF NOT EXISTS _duxcel_workspace;
CREATE TABLE _duxcel_workspace.cells(sheet_id INTEGER, row_id UBIGINT, column_id INTEGER, "text" VARCHAR, PRIMARY KEY(sheet_id, row_id, column_id));
CREATE TABLE _duxcel_workspace."columns"(sheet_id INTEGER, column_id INTEGER, "name" VARCHAR, width DOUBLE, PRIMARY KEY(sheet_id, column_id));
CREATE TABLE _duxcel_workspace.filters(sheet_id INTEGER, "position" INTEGER, "name" VARCHAR, op INTEGER, "value" VARCHAR, PRIMARY KEY(sheet_id, "position"));
CREATE TABLE _duxcel_workspace.formats(sheet_id INTEGER, "position" INTEGER, r0 UBIGINT, r1 UBIGINT, c0 INTEGER, c1 INTEGER, mask INTEGER, flags INTEGER, alignment INTEGER, color INTEGER, font_size INTEGER, numeric_format INTEGER, decimals INTEGER, PRIMARY KEY(sheet_id, "position"));
CREATE TABLE _duxcel_workspace.marks(sheet_id INTEGER, object_id UBIGINT, "role" INTEGER, "position" INTEGER, "name" VARCHAR, is_measure BOOLEAN, "aggregate" INTEGER, grain INTEGER, PRIMARY KEY(sheet_id, object_id, "role", "position"));
CREATE TABLE _duxcel_workspace.meta("version" INTEGER, active_sheet UBIGINT, user_scale DOUBLE);
CREATE TABLE _duxcel_workspace.objects(sheet_id INTEGER, id UBIGINT, "name" VARCHAR, row_id UBIGINT, column_id INTEGER, height UBIGINT, width INTEGER, kind INTEGER DEFAULT(0), mark INTEGER DEFAULT(0), source_id UBIGINT DEFAULT(0), chart_measure INTEGER DEFAULT(0), PRIMARY KEY(sheet_id, id));
CREATE TABLE _duxcel_workspace.pivot_fields(sheet_id INTEGER, object_id UBIGINT, "role" INTEGER, "position" INTEGER, "name" VARCHAR, "aggregate" INTEGER, filter_op INTEGER, "value" VARCHAR, grain INTEGER DEFAULT(0), PRIMARY KEY(sheet_id, object_id, "role", "position"));
CREATE TABLE _duxcel_workspace.preferences("name" VARCHAR PRIMARY KEY, "value" BOOLEAN);
CREATE TABLE _duxcel_workspace.queries(sheet_id INTEGER, object_id UBIGINT, query VARCHAR, PRIMARY KEY(sheet_id, object_id));
CREATE TABLE _duxcel_workspace.sheets(id INTEGER PRIMARY KEY, "name" VARCHAR, kind INTEGER, path VARCHAR, source_schema VARCHAR, source_table VARCHAR, filter_column VARCHAR, filter_value VARCHAR, filter_op INTEGER, group_column VARCHAR, measure_column VARCHAR, "aggregate" INTEGER, sort_column VARCHAR, descending BOOLEAN, active_row UBIGINT, active_col UBIGINT, anchor_row UBIGINT, anchor_col UBIGINT, end_row UBIGINT, end_col UBIGINT, top_row UBIGINT, horizontal DOUBLE, fraction DOUBLE, selection INTEGER, canvas_zoom DOUBLE DEFAULT(1));
CREATE TABLE _duxcel_workspace.sorts(sheet_id INTEGER, "position" INTEGER, "name" VARCHAR, descending BOOLEAN, PRIMARY KEY(sheet_id, "position"));
CREATE TABLE _duxcel_workspace.source_options(sheet_id INTEGER, object_id UBIGINT, unique_rows BOOLEAN, PRIMARY KEY(sheet_id, object_id));
CREATE TABLE _duxcel_workspace.table_filters(sheet_id INTEGER, object_id UBIGINT, "position" INTEGER, "name" VARCHAR, op INTEGER, "value" VARCHAR, PRIMARY KEY(sheet_id, object_id, "position"));
CREATE TABLE _duxcel_workspace.table_sorts(sheet_id INTEGER, object_id UBIGINT, "position" INTEGER, "name" VARCHAR, descending BOOLEAN, PRIMARY KEY(sheet_id, object_id, "position"));
CREATE TABLE _duxcel_workspace.table_sources(sheet_id INTEGER, object_id UBIGINT, kind INTEGER, path VARCHAR, source_schema VARCHAR, source_table VARCHAR, filter_column VARCHAR, filter_value VARCHAR, filter_op INTEGER, group_column VARCHAR, measure_column VARCHAR, "aggregate" INTEGER, sort_column VARCHAR, descending BOOLEAN, PRIMARY KEY(sheet_id, object_id));
COMMIT;
